      var r=parseInt(h.slice(0,2),16),gg=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16);
      document.documentElement.style.setProperty('--ac-rgb',r+','+gg+','+b);
    }
  }

  g('w-locname').textContent=d.location||t('Unknown Location','ยังไม่ทราบสถานที่');
  g('w-locterr').textContent=d.territory||'';
  g('w-hero-name').textContent=d.location||t('Unknown Location','ยังไม่ทราบสถานที่');
  g('w-hero-terr').textContent=d.territory||'';
