  g('w-hero-cal').textContent=d.calendarSystem?(t('Reckoning: ','ปฏิทินที่ใช้: ')+d.calendarSystem):'';

  var dv=d.dangerLevel!=null?Math.max(0,Math.min(10,parseFloat(d.dangerLevel))):null;
