  g('w-danger').innerHTML='<svg width="10" height="10" viewBox="0 0 24 24" fill="'+dc+'"><path d="M12 2l2.6 6.6L21 9.3l-5 4.6L17.3 21 12 17.3 6.7 21 8 13.9 3 9.3l6.4-.7Z"/></svg>'+(dv!=null?dv.toFixed(0)+'/10':t('—','—'));
  g('w-danger').style.color=dc;
  g('w-danger').style.borderColor=dc;
  g('w-danger').style.background='transparent';
  g('w-danger-val').textContent=dv!=null?(dv.toFixed(0)+' / 10'):'—';
  g('w-danger-val').style.color=dc;
  g('w-danger-fill').style.width=(dv!=null?dv*10:0)+'%';
  g('w-danger-fill').style.background=dc;

  var wi=weatherInfo(d.weather);
