    var lvl=standingLevel(f.standing,f.level);
    var color=lvl?STANDING_COLORS[lvl-1]:'var(--mu)';
    var pips='';
    for(var i=1;i<=5;i++)pips+='<div class="w-fac-pip" style="'+(i<=lvl?'background:'+color:'')+'"></div>';
    return '<div class="w-fac"><div class="w-fac-head"><div class="w-fac-name">'+esc(f.name||'')+'</div>'+
      '<div class="w-fac-standing" style="color:'+color+';background:rgba(0,0,0,.2);border:1px solid '+color+'66">'+esc(f.standing||t('Unknown','ไม่ทราบ'))+'</div></div>'+
      '<div class="w-fac-pips">'+pips+'</div>'+
      (f.note?'<div class="w-fac-note">'+esc(f.note)+'</div>':'')+
    '</div>';
  }).join(''):emptyMsg('No factions tracked yet.','ยังไม่มีการบันทึกกลุ่มอิทธิพลใดๆ');
  g('w-factions-wrap').innerHTML=facHtml;

  g('w-royalcoin').textContent=d.royalCoin||'—';
  g('w-chits').textContent=d.hollowChits||'—';

  // Journey
  var journey=d.journey||[];
  var jHtml=journey.length?journey.map(function(j){
    return accordion(j.name||'',j.territory||null,j.summary||'',j.details||j.summary||'');
  }).join(''):emptyMsg('No places discovered yet.','ยังไม่มีสถานที่ที่ถูกค้นพบ');
  g('w-journey-wrap').innerHTML=jHtml;
}

